/**
 * DimensionBanner editing behavior (#2148) — the per-unit edit affordance on
 * the 2 always-visible dimension summaries. Read-mode markup (heading,
 * accent classes, RTL-safety) is already covered by
 * `tests/components/pmesii-cards.test.tsx`; this file covers only the
 * opt-in edit lifecycle: enter/save/cancel/escape, in-flight disabling,
 * failure/conflict rendering, the translated-content edit gate, and the
 * documented prop-resync divergence from `ContentSourcesCard.tsx`.
 */
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import DimensionBanner from "../../../src/components/pmesii/DimensionBanner";
import { RangeApiError } from "../../../src/api/exercises";

const TITLE = m.range_pmesii_physical_title();
const SUMMARY = "A compact, highly urbanized coastal state.";

describe("DimensionBanner — read-only mode (onSave absent)", () => {
  test("renders exactly the read-only markup: no Edit control, no textarea", () => {
    render(<DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" />);
    expect(screen.getByText(SUMMARY)).toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }),
    ).not.toBeInTheDocument();
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(
      screen.queryByText(m.range_pmesii_edit_original_hint()),
    ).not.toBeInTheDocument();
  });
});

describe("DimensionBanner — edit lifecycle (onSave provided)", () => {
  test("Edit enters edit mode with a textarea pre-filled with the summary", async () => {
    const user = userEvent.setup();
    render(
      <DimensionBanner
        title={TITLE}
        summary={SUMMARY}
        accent="physical"
        onSave={vi.fn().mockResolvedValue(undefined)}
      />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    const textarea = screen.getByRole("textbox") as HTMLTextAreaElement;
    expect(textarea.value).toBe(SUMMARY);
    expect(
      screen.getByRole("button", { name: m.range_pmesii_save_action() }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: m.range_pmesii_cancel_action() }),
    ).toBeInTheDocument();
  });

  test("Save calls onSave with the edited value and exits edit mode", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockResolvedValue(undefined);
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    const textarea = screen.getByRole("textbox");
    await user.clear(textarea);
    await user.type(textarea, "Updated summary text.");
    await user.click(screen.getByRole("button", { name: m.range_pmesii_save_action() }));

    await waitFor(() => expect(onSave).toHaveBeenCalledWith("Updated summary text."));
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    // Focus returns to the Edit control on exit.
    expect(
      screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }),
    ).toHaveFocus();
  });

  test("Cancel restores the original value and exits edit mode without saving", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockResolvedValue(undefined);
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.clear(screen.getByRole("textbox"));
    await user.type(screen.getByRole("textbox"), "Discarded draft.");
    await user.click(screen.getByRole("button", { name: m.range_pmesii_cancel_action() }));

    expect(onSave).not.toHaveBeenCalled();
    expect(screen.getByText(SUMMARY)).toBeInTheDocument();
    expect(screen.queryByText("Discarded draft.")).not.toBeInTheDocument();
  });

  test("Escape cancels the edit", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockResolvedValue(undefined);
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.type(screen.getByRole("textbox"), " more");
    await user.keyboard("{Escape}");

    expect(onSave).not.toHaveBeenCalled();
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(screen.getByText(SUMMARY)).toBeInTheDocument();
  });

  test("in-flight save disables the textarea and both controls, and marks Save aria-busy", async () => {
    const user = userEvent.setup();
    let resolveSave: () => void = () => undefined;
    const onSave = vi.fn(
      () =>
        new Promise<void>((resolve) => {
          resolveSave = resolve;
        }),
    );
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.click(screen.getByRole("button", { name: m.range_pmesii_save_action() }));

    const saveBtn = screen.getByRole("button", { name: m.range_pmesii_save_action() });
    const cancelBtn = screen.getByRole("button", { name: m.range_pmesii_cancel_action() });
    expect(saveBtn).toBeDisabled();
    expect(saveBtn).toHaveAttribute("aria-busy", "true");
    expect(cancelBtn).toBeDisabled();
    expect(screen.getByRole("textbox")).toBeDisabled();

    resolveSave();
    await waitFor(() => expect(screen.queryByRole("textbox")).not.toBeInTheDocument());
  });

  test("a rejected non-conflict save renders an inline role=alert and stays in edit mode", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockRejectedValue(new Error("Network unreachable"));
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.click(screen.getByRole("button", { name: m.range_pmesii_save_action() }));

    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent(
      m.range_pmesii_save_failed({ message: "Network unreachable" }),
    );
    // Still editing — the instructor can retry.
    expect(screen.getByRole("textbox")).toBeInTheDocument();
  });

  test("a 409 RangeApiError renders the conflict message and exits edit mode", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockRejectedValue(new RangeApiError(409, "stale"));
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.click(screen.getByRole("button", { name: m.range_pmesii_save_action() }));

    const alert = await screen.findByRole("alert");
    expect(alert).toHaveTextContent(m.range_pmesii_save_conflict());
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
  });
});

describe("DimensionBanner — translation edit gate (isCanonical)", () => {
  test("isCanonical=false replaces Edit with the 'switch to original' hint", () => {
    render(
      <DimensionBanner
        title={TITLE}
        summary={SUMMARY}
        accent="physical"
        isCanonical={false}
        onSave={vi.fn()}
      />,
    );
    expect(
      screen.queryByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }),
    ).not.toBeInTheDocument();
    expect(screen.getByText(m.range_pmesii_edit_original_hint())).toBeInTheDocument();
  });

  test("isCanonical defaults to true when omitted", () => {
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={vi.fn()} />,
    );
    expect(
      screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }),
    ).toBeInTheDocument();
  });
});

describe("DimensionBanner — prop resync (ContentSourcesCard.tsx:161 divergence)", () => {
  test("resyncs the displayed summary from props while idle", () => {
    const { rerender } = render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" />,
    );
    rerender(<DimensionBanner title={TITLE} summary="A newly regenerated summary." accent="physical" />);
    expect(screen.getByText("A newly regenerated summary.")).toBeInTheDocument();
  });

  test("a summary prop change mid-edit exits edit mode and discards the draft, instead of silently overwriting it", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockResolvedValue(undefined);
    const { rerender } = render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.type(screen.getByRole("textbox"), " live edit in progress");

    rerender(
      <DimensionBanner
        title={TITLE}
        summary="Someone else's edit landed."
        accent="physical"
        onSave={onSave}
      />,
    );

    // Edit mode is exited outright — the live draft is discarded, not
    // silently overwritten with the new prop value mid-keystroke.
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(screen.getByText("Someone else's edit landed.")).toBeInTheDocument();
    expect(onSave).not.toHaveBeenCalled();
  });
});


