/**
 * PMESIIPanel tests — the four status states (computing/error/pending/ready),
 * the regenerate/retry affordance, the generated-at caption, and the optional
 * TranslationBar mount condition (issue #479).
 */
import { render, screen, within } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { vi, describe, it, expect, beforeEach, afterEach } from "vitest";
import { ToastHost, __resetToasts } from "@omnicore-platform/platform-chrome/toast";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import PMESIIPanel, { formatGeneratedAt } from "../../../src/components/pmesii/PMESIIPanel";
import { allFieldSpecs } from "../../../src/components/pmesii/fieldSpec";
import type { SubSectionSaveHandler } from "../../../src/components/pmesii/SubSectionCard";
import type { UseEnvironmentAnalysisEditingResult } from "../../../src/hooks/useEnvironmentAnalysis";
import { makeAnalysis } from "../../fixtures/analysis";
vi.mock("../../../src/api/analysis", async () => {
  const actual =
    await vi.importActual<typeof import("../../../src/api/analysis")>(
      "../../../src/api/analysis",
    );
  return {
    ...actual,
    updateEnvironmentAnalysisForDraft: vi.fn(),
  };
});

import { updateEnvironmentAnalysisForDraft } from "../../../src/api/analysis";
import { useEnvironmentAnalysisEditing } from "../../../src/hooks/useEnvironmentAnalysis";

const updateForDraftMock = vi.mocked(updateEnvironmentAnalysisForDraft);

/** Mounts PMESIIPanel wired to the REAL save-orchestration hook (never a
 * mock of saveSection itself), so the round-trip test below exercises the
 * actual `(sectionKey, label) -> fieldKey` resolution this task exists to
 * keep from throwing. */
function EditingHarness({
  analysis,
}: {
  readonly analysis: ReturnType<typeof makeAnalysis>;
}) {
  const editing = useEnvironmentAnalysisEditing({
    analysis,
    draftId: "draft-1",
    locale: "en-US",
    showOriginal: false,
  });
  return (
    <>
      <ToastHost />
      <PMESIIPanel status="ready" analysis={editing.analysis} editing={editing} />
    </>
  );
}

describe("PMESIIPanel", () => {
  it("renders a polite status spinner while computing", () => {
    render(<PMESIIPanel status="computing" analysis={null} />);
    expect(screen.getByRole("status")).toHaveTextContent(
      m.range_pmesii_computing(),
    );
  });

  it("renders a danger alert with the default body on error", () => {
    render(<PMESIIPanel status="error" analysis={null} />);
    const alert = screen.getByRole("alert");
    expect(alert).toHaveTextContent(m.range_pmesii_error());
    expect(alert).toHaveTextContent(m.range_pmesii_error_body());
  });

  it("renders a custom error message when provided", () => {
    render(
      <PMESIIPanel status="error" analysis={null} errorMessage="boom failed" />,
    );
    expect(screen.getByRole("alert")).toHaveTextContent("boom failed");
  });

  it("retry button on error invokes onRegenerate", async () => {
    const user = userEvent.setup();
    const onRegenerate = vi.fn();
    render(
      <PMESIIPanel
        status="error"
        analysis={null}
        onRegenerate={onRegenerate}
      />,
    );
    await user.click(
      screen.getByRole("button", { name: m.range_pmesii_retry_action() }),
    );
    expect(onRegenerate).toHaveBeenCalledTimes(1);
  });

  it("renders the pending card with a generate CTA when onRegenerate is given", async () => {
    const user = userEvent.setup();
    const onRegenerate = vi.fn();
    render(
      <PMESIIPanel
        status="pending"
        analysis={null}
        onRegenerate={onRegenerate}
      />,
    );
    expect(
      screen.getByText(m.range_pmesii_pending_title()),
    ).toBeInTheDocument();
    await user.click(
      screen.getByRole("button", { name: m.range_pmesii_generate_action() }),
    );
    expect(onRegenerate).toHaveBeenCalledTimes(1);
  });

  it("omits the generate CTA in the pending card when onRegenerate is absent", () => {
    render(<PMESIIPanel status="pending" analysis={null} />);
    expect(
      screen.queryByRole("button", { name: m.range_pmesii_generate_action() }),
    ).not.toBeInTheDocument();
  });

  it("falls back to the pending card when status is ready but analysis is null", () => {
    render(<PMESIIPanel status="ready" analysis={null} />);
    expect(screen.getByText(m.range_pmesii_pending_title())).toBeInTheDocument();
  });

  it("renders both dimension banners and the generated-at caption when ready", () => {
    render(
      <PMESIIPanel
        status="ready"
        analysis={makeAnalysis({ generated_at: "2026-06-01T10:00:00Z" })}
      />,
    );
    expect(screen.getByText(m.range_pmesii_physical_title())).toBeInTheDocument();
    expect(
      screen.getByText(m.range_pmesii_informational_title()),
    ).toBeInTheDocument();
    // a known physical field value renders
    expect(screen.getByText("Coastal lowlands")).toBeInTheDocument();
  });

  it("hides the generated-at caption when showGeneratedAt is false", () => {
    const analysis = makeAnalysis({ generated_at: "2026-06-01T10:00:00Z" });
    render(
      <PMESIIPanel
        status="ready"
        analysis={analysis}
        showGeneratedAt={false}
      />,
    );
    expect(
      screen.queryByText(
        m.range_pmesii_generated_at({
          when: formatGeneratedAt("2026-06-01T10:00:00Z"),
        }),
      ),
    ).not.toBeInTheDocument();
  });

  it("mounts the TranslationBar only when source and target locale names differ", () => {
    render(
      <PMESIIPanel
        status="ready"
        analysis={makeAnalysis()}
        translationState="idle"
        sourceLocaleName="English"
        targetLocaleName="German"
        onTranslate={vi.fn()}
      />,
    );
    expect(
      screen.getByRole("button", {
        name: m.range_pmesii_translate_action({ locale: "German" }),
      }),
    ).toBeInTheDocument();
  });

  it("omits the TranslationBar when source and target locale names match", () => {
    render(
      <PMESIIPanel
        status="ready"
        analysis={makeAnalysis()}
        translationState="idle"
        sourceLocaleName="English"
        targetLocaleName="English"
      />,
    );
    expect(
      screen.queryByRole("button", {
        name: m.range_pmesii_translate_action({ locale: "English" }),
      }),
    ).not.toBeInTheDocument();
  });

  it("mounts the TranslationBar with no-op fallbacks when its callbacks are omitted", async () => {
    const user = userEvent.setup();
    // No onTranslate / onToggleOriginal / onDismissTranslationError → the
    // `?? (() => undefined)` fallback arrows must be wired so the bar's own
    // buttons stay clickable without throwing.
    render(
      <PMESIIPanel
        status="ready"
        analysis={makeAnalysis()}
        translationState="idle"
        sourceLocaleName="English"
        targetLocaleName="German"
      />,
    );
    const translateBtn = screen.getByRole("button", {
      name: m.range_pmesii_translate_action({ locale: "German" }),
    });
    // Clicking invokes the no-op fallback — no throw, button stays present.
    await user.click(translateBtn);
    expect(translateBtn).toBeInTheDocument();
  });

  it("formatGeneratedAt returns the raw ISO string when unparseable", () => {
    expect(formatGeneratedAt("not-a-date")).toBe("not-a-date");
  });
});

// ─── Editing wire-up (#2148/T15a) ───────────────────────────────────────────

function makeFakeEditing(
  overrides: Partial<UseEnvironmentAnalysisEditingResult> = {},
): UseEnvironmentAnalysisEditingResult {
  return {
    analysis: makeAnalysis(),
    isCanonical: true,
    disabledReason: undefined,
    saveSection: vi.fn() as unknown as SubSectionSaveHandler,
    savePhysicalSummary: vi.fn().mockResolvedValue(undefined),
    saveInformationalSummary: vi.fn().mockResolvedValue(undefined),
    ...overrides,
  };
}

// The Edit control's accessible name is `range_pmesii_field_edit_aria`
// ("Edit {field}") — not the bare `range_pmesii_edit_action` visible-text
// copy — so every lookup below matches on the shared "Edit " prefix.
const editButtonName = new RegExp(`^${m.range_pmesii_edit_action()}`);

/**
 * `expectSectionExpanded` (accordionAssertions.ts) matches the trigger by
 * accessible-name substring — which collides with the new Edit button's
 * "Edit {section}" aria-label once editing is on (both contain the section
 * title), so it can't be reused unmodified here. This local variant scopes
 * the lookup to the Expand/Collapse-prefixed trigger specifically.
 */
function expectCardExpanded(sectionTitle: string): void {
  const trigger = screen.getByRole("button", {
    name: (accessibleName) =>
      /^(Expand|Collapse)\b/.test(accessibleName) &&
      accessibleName.includes(sectionTitle),
  });
  expect(trigger).toHaveAttribute("data-state", "open");
  expect(trigger).toHaveAttribute("aria-expanded", "true");
}

describe("PMESIIPanel — editing prop (#2148/T15a)", () => {
  it("without `editing`, renders read-only with no Edit affordances (dashboard guard)", () => {
    render(<PMESIIPanel status="ready" analysis={makeAnalysis()} />);
    expect(
      screen.queryByRole("button", { name: editButtonName }),
    ).not.toBeInTheDocument();
  });

  it("with `editing`, renders an Edit control on all 8 sub-section cards and both summaries", () => {
    const editing = makeFakeEditing();
    render(
      <PMESIIPanel status="ready" analysis={makeAnalysis()} editing={editing} />,
    );
    // 8 sub-section cards + 2 dimension-summary banners = 10 Edit controls.
    expect(
      screen.getAllByRole("button", { name: editButtonName }),
    ).toHaveLength(10);
  });

  it("forwards the real fieldSpec sectionKey (not the localized title) as the Accordion item value", () => {
    const editing = makeFakeEditing();
    render(
      <PMESIIPanel status="ready" analysis={makeAnalysis()} editing={editing} />,
    );
    // The trigger's aria-controls id is Radix-generated per item value; the
    // proof that `sectionKey` (not `title`) is wired is that every section
    // still starts expanded (below) AND that a save reaches saveSection with
    // the fieldSpec key, asserted in the "save reaches saveSection" test.
    expectCardExpanded(m.range_pmesii_section_geography());
  });

  it("all sections still default to expanded once items are keyed by sectionKey", () => {
    const editing = makeFakeEditing();
    render(
      <PMESIIPanel status="ready" analysis={makeAnalysis()} editing={editing} />,
    );
    expectCardExpanded(m.range_pmesii_section_geography());
    expectCardExpanded(m.range_pmesii_section_demographics());
    expectCardExpanded(m.range_pmesii_section_infrastructure());
    expectCardExpanded(m.range_pmesii_section_economic());
    expectCardExpanded(m.range_pmesii_section_media_landscape());
    expectCardExpanded(m.range_pmesii_section_information_infrastructure());
    expectCardExpanded(m.range_pmesii_section_trust_dynamics());
    expectCardExpanded(m.range_pmesii_section_information_flow());
  });

  it("a save from the Geography card reaches editing.saveSection with sectionKey='geography'", async () => {
    const user = userEvent.setup();
    const saveSection = vi.fn().mockResolvedValue(undefined);
    const editing = makeFakeEditing({ saveSection });
    render(
      <PMESIIPanel status="ready" analysis={makeAnalysis()} editing={editing} />,
    );
    const geographyHeading = screen.getByRole("heading", {
      level: 4,
      name: m.range_pmesii_section_geography(),
    });
    const card = geographyHeading.closest('[data-testid="subsection-card"]') as HTMLElement;
    await user.click(
      within(card).getByRole("button", { name: editButtonName }),
    );
    await user.click(
      within(card).getByRole("button", { name: m.range_pmesii_save_action() }),
    );
    expect(saveSection).toHaveBeenCalledTimes(1);
    expect(saveSection.mock.calls[0]?.[0]).toBe("geography");
  });

  it("uses the fieldSpec label (not the raw fieldKey) for the sectionKey/label pairs a resolve depends on", () => {
    // Sanity-pin: every field rendered by physicalSections/informationalSections
    // (which SubSectionCard's edit form saves back out) carries a label that
    // exists in allFieldSpecs under that same sectionKey — otherwise the save
    // orchestration's resolveFieldKey would throw.
    for (const spec of allFieldSpecs()) {
      expect(
        allFieldSpecs().some(
          (f) => f.sectionKey === spec.sectionKey && f.label === spec.label,
        ),
      ).toBe(true);
    }
  });

  describe("round-trip through the REAL useEnvironmentAnalysisEditing hook", () => {
    beforeEach(() => {
      updateForDraftMock.mockReset();
    });
    afterEach(() => {
      __resetToasts();
    });

    it("an edited sub-section field saves without throwing the unresolvable-label error", async () => {
      const user = userEvent.setup();
      const analysis = makeAnalysis();
      updateForDraftMock.mockResolvedValue(
        makeAnalysis({
          physical_dimension: {
            ...analysis.physical_dimension,
            geography: { ...analysis.physical_dimension.geography, terrain: "Edited terrain" },
          },
        }),
      );

      render(<EditingHarness analysis={analysis} />);

      const geographyHeading = screen.getByRole("heading", {
        level: 4,
        name: m.range_pmesii_section_geography(),
      });
      const card = geographyHeading.closest('[data-testid="subsection-card"]') as HTMLElement;
      await user.click(
        within(card).getByRole("button", { name: editButtonName }),
      );
      const terrainInput = within(card).getByLabelText(
        m.range_pmesii_field_terrain(),
      );
      await user.clear(terrainInput);
      await user.type(terrainInput, "Edited terrain");
      await user.click(
        within(card).getByRole("button", { name: m.range_pmesii_save_action() }),
      );

      // No inline alert (the unresolvable-label throw would surface as a
      // rejected save, which SubSectionEditForm renders as role="alert").
      expect(within(card).queryByRole("alert")).not.toBeInTheDocument();
      expect(updateForDraftMock).toHaveBeenCalledTimes(1);
      const [, input] = updateForDraftMock.mock.calls[0] as [string, { physical_dimension: { geography: { terrain: string } } }];
      expect(input.physical_dimension.geography.terrain).toBe("Edited terrain");
    });

    it("an edited dimension summary saves without throwing", async () => {
      const user = userEvent.setup();
      const analysis = makeAnalysis();
      updateForDraftMock.mockResolvedValue(
        makeAnalysis({
