describe("useReturnFocusOnExit", () => {
  function Harness() {
    const [editing, setEditing] = useState(true);
    const { editBtnRef, markExit } = useReturnFocusOnExit(editing);
    return (
      <div>
        <button ref={editBtnRef} type="button">
          Edit
        </button>
        <button
          type="button"
          onClick={() => {
            markExit();
            setEditing(false);
          }}
        >
          Save
        </button>
        <button type="button" onClick={() => setEditing(false)}>
          Silent exit
        </button>
      </div>
    );
  }

  test("does not focus the edit button on an exit that never called markExit", async () => {
    const user = userEvent.setup();
    render(<Harness />);
    await user.click(screen.getByRole("button", { name: "Silent exit" }));
    expect(screen.getByRole("button", { name: "Edit" })).not.toHaveFocus();
  });

  test("focuses the edit button when exit was preceded by markExit", async () => {
    const user = userEvent.setup();
    render(<Harness />);
    await user.click(screen.getByRole("button", { name: "Save" }));
    expect(screen.getByRole("button", { name: "Edit" })).toHaveFocus();
  });

  test("editBtnRef starts out null and is populated once mounted", () => {
    const { result } = renderHook(() => useReturnFocusOnExit(true));
    expect(result.current.editBtnRef.current).toBeNull();
  });
});


