/**
 * DimensionBanner editing behavior (#2148) — the per-unit edit affordance on
 * the 2 always-visible dimension summaries. Read-mode markup (heading,
 * accent classes, RTL-safety) is already covered by
 * `tests/components/pmesii-cards.test.tsx`; this file covers only the
 * opt-in edit lifecycle: enter/save/cancel/escape, in-flight disabling,
 * failure/conflict rendering, the translated-content edit gate, and the
 * documented prop-resync divergence from `ContentSourcesCard.tsx`.
 */
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import DimensionBanner from "../../../src/components/pmesii/DimensionBanner";
import { RangeApiError } from "../../../src/api/exercises";

const TITLE = m.range_pmesii_physical_title();
const SUMMARY = "A compact, highly urbanized coastal state.";

describe("DimensionBanner — read-only mode (onSave absent)", () => {
  test("renders exactly the read-only markup: no Edit control, no textarea", () => {
    render(<DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" />);
    expect(screen.getByText(SUMMARY)).toBeInTheDocument();
    expect(
      screen.queryByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }),
    ).not.toBeInTheDocument();
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
