      screen.queryByText(m.range_pmesii_edit_original_hint()),
    ).not.toBeInTheDocument();
  });
});

describe("DimensionBanner — edit lifecycle (onSave provided)", () => {
  test("Edit enters edit mode with a textarea pre-filled with the summary", async () => {
    const user = userEvent.setup();
    render(
      <DimensionBanner
        title={TITLE}
        summary={SUMMARY}
        accent="physical"
        onSave={vi.fn().mockResolvedValue(undefined)}
      />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    const textarea = screen.getByRole("textbox") as HTMLTextAreaElement;
    expect(textarea.value).toBe(SUMMARY);
    expect(
      screen.getByRole("button", { name: m.range_pmesii_save_action() }),
    ).toBeInTheDocument();
    expect(
      screen.getByRole("button", { name: m.range_pmesii_cancel_action() }),
    ).toBeInTheDocument();
  });

  test("Save calls onSave with the edited value and exits edit mode", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockResolvedValue(undefined);
    render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    const textarea = screen.getByRole("textbox");
    await user.clear(textarea);
    await user.type(textarea, "Updated summary text.");
    await user.click(screen.getByRole("button", { name: m.range_pmesii_save_action() }));

    await waitFor(() => expect(onSave).toHaveBeenCalledWith("Updated summary text."));
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    // Focus returns to the Edit control on exit.
    expect(
      screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }),
    ).toHaveFocus();
