describe("DimensionBanner — prop resync (ContentSourcesCard.tsx:161 divergence)", () => {
  test("resyncs the displayed summary from props while idle", () => {
    const { rerender } = render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" />,
    );
    rerender(<DimensionBanner title={TITLE} summary="A newly regenerated summary." accent="physical" />);
    expect(screen.getByText("A newly regenerated summary.")).toBeInTheDocument();
  });

  test("a summary prop change mid-edit exits edit mode and discards the draft, instead of silently overwriting it", async () => {
    const user = userEvent.setup();
    const onSave = vi.fn().mockResolvedValue(undefined);
    const { rerender } = render(
      <DimensionBanner title={TITLE} summary={SUMMARY} accent="physical" onSave={onSave} />,
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: TITLE }) }));
    await user.type(screen.getByRole("textbox"), " live edit in progress");

    rerender(
      <DimensionBanner
        title={TITLE}
        summary="Someone else's edit landed."
        accent="physical"
        onSave={onSave}
      />,
    );

    // Edit mode is exited outright — the live draft is discarded, not
    // silently overwritten with the new prop value mid-keystroke.
    expect(screen.queryByRole("textbox")).not.toBeInTheDocument();
    expect(screen.getByText("Someone else's edit landed.")).toBeInTheDocument();
    expect(onSave).not.toHaveBeenCalled();
  });
});


