/**
 * SubSectionCard collapse behavior (#2149) — Accordion.Item/Trigger/Content
 * conversion. Read-markup assertions (heading, dt/dd rows, empty-field
 * filter) live in tests/components/pmesii-cards.test.tsx; this file covers
 * the collapse/expand interaction and the multi-instance id-uniqueness
 * guarantee.
 *
 * `Accordion.Content` uses `forceMount` (frontends/ui/src/Accordion.tsx) so
 * collapsed content stays mounted — every collapse assertion here goes
 * through `expectSectionCollapsed` (never a presence query).
 */
import { render, screen, waitFor } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { Accordion } from "@omnicore-platform/ui";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import SubSectionCard, {
  type SubSectionCardProps,
} from "../../../src/components/pmesii/SubSectionCard";
import {
  expectSectionCollapsed,
  expectSectionExpanded,
} from "../../utils/accordionAssertions";

// SubSectionCard no longer owns its own Accordion.Root (#2149 — the Root is
// lifted to PMESIIPanel, one per dimension, so multiple cards can share a
// `type="multiple"` open/closed state). Tests render the card(s) inside a
// stand-in Root that mirrors PMESIIPanel's real usage.
function renderCard(title = m.range_pmesii_section_geography()) {
  return render(
    <Accordion.Root type="multiple" defaultValue={[title]}>
      <SubSectionCard
        title={title}
        fields={[
          { label: m.range_pmesii_field_terrain(), value: "Coastal lowlands" },
          { label: m.range_pmesii_field_climate(), value: "Humid continental" },
        ]}
      />
    </Accordion.Root>,
  );
}

test("renders expanded by default", () => {
  renderCard();
  expectSectionExpanded(m.range_pmesii_section_geography());
  expect(
    screen.getByText(m.range_pmesii_field_terrain()),
  ).toBeVisible();
});

test("clicking the trigger collapses the section", async () => {
