  });

  test("Cancel exits the edit form back to the read-only dl without saving", async () => {
    const user = userEvent.setup();
    const { onSave, title } = renderEditableCard();
    await user.click(
      screen.getByRole("button", { name: m.range_pmesii_field_edit_aria({ field: title }) }),
    );
    await user.click(screen.getByRole("button", { name: m.range_pmesii_cancel_action() }));

    expect(onSave).not.toHaveBeenCalled();
    expect(screen.getByText("Coastal lowlands")).toBeInTheDocument();
    expect(screen.queryByRole("button", { name: m.range_pmesii_save_action() })).not.toBeInTheDocument();
  });

  test("disabledReason replaces the Edit control with the 'switch to original' hint", () => {
    renderEditableCard({ disabledReason: "Viewing a translation" });
    expect(
      screen.queryByRole("button", {
        name: m.range_pmesii_field_edit_aria({ field: m.range_pmesii_section_geography() }),
      }),
    ).not.toBeInTheDocument();
    expect(screen.getByText(m.range_pmesii_edit_original_hint())).toBeInTheDocument();
  });

  // Standalone from `accordionAssertions.ts`'s `expectSectionCollapsed`/
  // `expectSectionExpanded`: those match a trigger by *substring* of its
  // accessible name, which collides here — the Edit button's own
  // accessible name ("Edit Geography") also contains the section title. An
  // exact match against the real expand/collapse aria-label copy avoids
  // that collision while keeping the same "assert visibility, not
  // presence" discipline (forceMount keeps collapsed content in the DOM).
  function getCardTrigger(title: string): HTMLElement {
    const expandName = m.range_pmesii_section_expand_aria({ section: title });
    const collapseName = m.range_pmesii_section_collapse_aria({ section: title });
    return screen.getByRole("button", {
      name: (accessibleName) =>
        accessibleName === expandName || accessibleName === collapseName,
    });
  }

  function getCardContent(trigger: HTMLElement): HTMLElement {
    const contentId = trigger.getAttribute("aria-controls");
    expect(contentId).toBeTruthy();
    const content = document.getElementById(contentId as string);
    expect(content).not.toBeNull();
    return content as HTMLElement;
  }

  function expectCardCollapsed(title: string): void {
    const trigger = getCardTrigger(title);
    expect(trigger).toHaveAttribute("data-state", "closed");
    const content = getCardContent(trigger);
    expect(content).toHaveAttribute("data-state", "closed");
    expect(content).not.toBeVisible();
  }

  function expectCardExpanded(title: string): void {
    const trigger = getCardTrigger(title);
    expect(trigger).toHaveAttribute("data-state", "open");
    const content = getCardContent(trigger);
    expect(content).toHaveAttribute("data-state", "open");
    expect(content).toBeVisible();
  }

  // BUG A (Node T3): the Edit control lives in the card header, outside
  // Accordion.Content, so it is clickable whether the item is open or
  // closed. But the edit form mounts INSIDE Accordion.Content, which
  // force-mounts and hides itself via `hidden` when collapsed
  // (frontends/ui/src/Accordion.tsx). Clicking Edit on a collapsed card must
  // therefore also open the item — asserted here on real visibility
  // (`toBeVisible`), never mere DOM presence, since forceMount would make a
  // presence query pass vacuously even while the panel stays hidden.
  test("clicking Edit on a COLLAPSED card opens the section so the edit form is actually visible", async () => {
    const user = userEvent.setup();
    const title = m.range_pmesii_section_geography();
    const onSave = vi.fn().mockResolvedValue(undefined);
    render(
      <Accordion.Root type="multiple" defaultValue={[]}>
        <SubSectionCard
          title={title}
          sectionKey="geography"
          fields={[{ label: m.range_pmesii_field_terrain(), value: "Coastal lowlands" }]}
          editable
          onSave={onSave}
        />
      </Accordion.Root>,
    );

    // Starts collapsed — and the Edit control is reachable even while closed.
    expectCardCollapsed(title);
    const editBtn = screen.getByRole("button", {
      name: m.range_pmesii_field_edit_aria({ field: title }),
    });
    expect(editBtn).toBeVisible();

    await user.click(editBtn);

    // The item must have opened — not just the `editing` flag flipping
    // behind a hidden panel.
    expectCardExpanded(title);
    expect(screen.getByDisplayValue("Coastal lowlands")).toBeVisible();
  });
});

// BUG B (Node T3): `sectionKey` must be required whenever `onSave` is
// supplied — a caller that enables editing without a real sectionKey
// produces a save whose sectionKey is a translated title, and
// `resolveFieldKey` (useEnvironmentAnalysis.ts) throws on the first Save.
// `SubSectionCardProps` is a discriminated union keyed off `onSave`'s
// presence, so this must be a COMPILE-time rejection, not a runtime one.
// `@ts-expect-error` here is the assertion itself: if the union regresses
// to allow this shape again, the now-unused directive fails `pnpm
// typecheck` — this is the standard way to prove a type is REJECTED, not a
// suppression of a real error.
function typeLevel_onSaveWithoutSectionKeyIsRejected(): SubSectionCardProps {
  // @ts-expect-error — onSave without sectionKey must not satisfy SubSectionCardProps (BUG B).
  return {
    title: "Geography",
    fields: [],
    editable: true,
    onSave: vi.fn(),
  };
}
void typeLevel_onSaveWithoutSectionKeyIsRejected;

test("multiple rendered cards use unique trigger/content id pairs", () => {
  render(
