/**
 * TranslationBar tests (issue #479 — explicit-translation affordance).
 *
 * The bar lets an instructor translate the canonical (source-language) PMESII
 * analysis into the UI language and toggle back to the original. It is a pure
 * presentational component driven by a `translationState` discriminated value;
 * all network/job wiring lives in the caller (useEnvironmentAnalysis /
 * StepAnalysis).
 *
 * a11y invariants asserted per state:
 *   idle        → ghost "Translate to <locale>" button fires onTranslate.
 *   translating → role="status" aria-live="polite" busy region.
 *   ready       → aria-pressed toggle flipping Show original / Show translated.
 *   error       → role="alert" danger region + dismiss button fires onDismissError.
 *
 * Strings are asserted via the same m.*() Paraglide functions the component
 * renders — never literal English.
 */

import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";

import TranslationBar from "../../../src/components/pmesii/TranslationBar";

const baseProps = {
  sourceLocaleName: "English",
  targetLocaleName: "Deutsch",
  showOriginal: false,
  onTranslate: vi.fn(),
  onToggleOriginal: vi.fn(),
  onDismissError: vi.fn(),
} as const;

describe("TranslationBar", () => {
  it("idle: renders a translate button that fires onTranslate", async () => {
    const user = userEvent.setup();
    const onTranslate = vi.fn();
    render(
      <TranslationBar
        {...baseProps}
        translationState="idle"
        onTranslate={onTranslate}
      />,
    );

    const btn = screen.getByRole("button", {
      name: m.range_pmesii_translate_action({ locale: "Deutsch" }),
    });
    await user.click(btn);
    expect(onTranslate).toHaveBeenCalledTimes(1);
